"use client";
import { ArtemisScope } from "./artemis-scope";
import Variant0 from "./components/flip-card/variants/01-default";
import Variant1 from "./components/flip-card/variants/02-modal";
const variants = { default: Variant0, modal: Variant1 };
export interface ArtemisFlipCardProps {
  className?: string;
  variant?: "default" | "modal";
}
export function ArtemisFlipCard({ className, variant = "default" }: ArtemisFlipCardProps) {
  const View = variants[variant];
  return (
    <ArtemisScope className={`art:[&>*]:mx-auto ${className ?? ""}`}>
      <View />
    </ArtemisScope>
  );
}
